import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

beforeAll(async () => {
    // Connect to test database
    await prisma.$connect();
});

afterAll(async () => {
    // Clean up and disconnect
    await prisma.$disconnect();
});

beforeEach(async () => {
    // Clean up database before each test
    await prisma.transaction.deleteMany({});
    await prisma.productCategory.deleteMany({});
    await prisma.product.deleteMany({});
    await prisma.category.deleteMany({});
    await prisma.user.deleteMany({});
});

export { prisma };

import { Container, Title, Card, Text, Badge, Group, Alert, LoadingOverlay, Stack, Tabs } from '@mantine/core';
import { useQuery } from '@apollo/client';
import { IconAlertCircle, IconShoppingCart, IconCalendar, IconCash, IconHandGrab } from '@tabler/icons-react';
import { GET_USER_TRANSACTIONS } from '../lib/graphql';
import { useAuth } from '../hooks/useAuth';
import type { Transaction } from '../types';
import { TransactionType, TransactionStatus } from '../types';
import { formatDate, formatDateRange } from '../utils/dateUtils';

const MyTransactions = () => {
    const { user } = useAuth();

    const { data, loading, error } = useQuery(GET_USER_TRANSACTIONS, {
        errorPolicy: 'all',
        fetchPolicy: 'cache-first', // Use cache first, only fetch if not cached
        skip: !user?.id
    });

    const getStatusColor = (status: TransactionStatus) => {
        switch (status) {
            case TransactionStatus.COMPLETED:
                return 'green';
            case TransactionStatus.PENDING:
                return 'orange';
            default:
                return 'gray';
        }
    };

    const getTypeIcon = (type: TransactionType) => {
        switch (type) {
            case TransactionType.BUY:
                return <IconShoppingCart size={16} />;
            case TransactionType.RENT:
                return <IconCalendar size={16} />;
            default:
                return null;
        }
    };

    // Using the shared date utility function

    if (loading) return <LoadingOverlay visible />;

    if (error) {
        return (
            <Container>
                <Alert icon={<IconAlertCircle size="1rem" />} title="Error!" color="red">
                    Failed to load transactions: {error.message}
                </Alert>
            </Container>
        );
    }

    const userTransactions = data?.getUserTransactions || { bought: [], sold: [], borrowed: [], lent: [] };

    // Calculate total transactions for empty state check
    const totalTransactions = (userTransactions.bought || []).length +
        (userTransactions.sold || []).length +
        (userTransactions.borrowed || []).length +
        (userTransactions.lent || []).length;

    const TransactionCard = ({ transaction }: { transaction: Transaction }) => {
        // Handle cases where product or owner might be null/undefined
        const productName = transaction.product?.name || 'Unknown Product';

        // Handle different data structures for different transaction types
        let otherPartyName = 'Unknown';
        let labelText = '';

        // Determine if this is a bought/borrowed transaction (user is buyer) or sold/lent transaction (user is seller)
        const isBoughtOrBorrowed = (userTransactions.bought || []).some((t: Transaction) => t.id === transaction.id) ||
            (userTransactions.borrowed || []).some((t: Transaction) => t.id === transaction.id);

        if (isBoughtOrBorrowed) {
            // For bought/borrowed items, show the seller/owner
            otherPartyName = transaction.product?.owner
                ? `${transaction.product.owner.firstname || ''} ${transaction.product.owner.lastname || ''}`.trim() || 'Unknown'
                : 'Unknown';
            labelText = transaction.type === TransactionType.BUY ? 'Purchased from' : 'Rented from';
        } else {
            // For sold/lent items, show the buyer/borrower
            const transactionWithUser = transaction as Transaction & {
                user?: { firstname?: string; lastname?: string }
            };
            otherPartyName = transactionWithUser.user
                ? `${transactionWithUser.user.firstname || ''} ${transactionWithUser.user.lastname || ''}`.trim() || 'Unknown'
                : 'Unknown';
            labelText = transaction.type === TransactionType.BUY ? 'Sold to' : 'Lent to';
        }

        return (
            <Card shadow="sm" padding="lg" radius="md" withBorder mb="md">
                <Group justify="space-between" mb="xs">
                    <Group>
                        {getTypeIcon(transaction.type)}
                        <Text fw={500}>
                            {productName}
                        </Text>
                    </Group>
                    <Badge color={getStatusColor(transaction.status)}>
                        {transaction.status.toLowerCase()}
                    </Badge>
                </Group>

                <Text size="sm" c="dimmed" mb="sm">
                    {labelText}: {otherPartyName}
                </Text>

                <Group justify="space-between" mb="sm">
                    <Text size="sm" fw={500}>
                        Price: ${transaction.price || 0}
                    </Text>
                    <Text size="sm" c="dimmed">
                        {formatDate(transaction.createdAt)}
                    </Text>
                </Group>

                {transaction.type === TransactionType.RENT && (
                    <Text size="sm" c="dimmed">
                        Period: {formatDateRange(transaction.startDate, transaction.endDate)}
                    </Text>
                )}
            </Card>
        );
    };

    return (
        <Container size="lg">
            <Title mb="xl">My Transactions</Title>

            {totalTransactions === 0 ? (
                <Card shadow="sm" padding="xl" radius="md" withBorder>
                    <Text ta="center" c="dimmed">
                        You haven't made any transactions yet.
                    </Text>
                </Card>
            ) : (
                <Tabs defaultValue="bought">
                    <Tabs.List>
                        <Tabs.Tab value="bought" leftSection={<IconShoppingCart size={16} />}>
                            Bought ({(userTransactions.bought || []).length})
                        </Tabs.Tab>
                        <Tabs.Tab value="sold" leftSection={<IconCash size={16} />}>
                            Sold ({(userTransactions.sold || []).length})
                        </Tabs.Tab>
                        <Tabs.Tab value="borrowed" leftSection={<IconCalendar size={16} />}>
                            Borrowed ({(userTransactions.borrowed || []).length})
                        </Tabs.Tab>
                        <Tabs.Tab value="lent" leftSection={<IconHandGrab size={16} />}>
                            Lent ({(userTransactions.lent || []).length})
                        </Tabs.Tab>
                    </Tabs.List>

                    <Tabs.Panel value="bought" pt="md">
                        <Title order={3} mb="md">Items I Bought</Title>
                        <Text size="sm" c="dimmed" mb="lg">
                            Products you purchased from others
                        </Text>
                        <Stack>
                            {(userTransactions.bought || []).length === 0 ? (
                                <Text c="dimmed" ta="center">You haven't bought any items yet</Text>
                            ) : (
                                (userTransactions.bought || []).map((transaction: Transaction) =>
                                    transaction && transaction.id ? (
                                        <TransactionCard key={transaction.id} transaction={transaction} />
                                    ) : null
                                )
                            )}
                        </Stack>
                    </Tabs.Panel>

                    <Tabs.Panel value="sold" pt="md">
                        <Title order={3} mb="md">Items I Sold</Title>
                        <Text size="sm" c="dimmed" mb="lg">
                            Products you sold to others
                        </Text>
                        <Stack>
                            {(userTransactions.sold || []).length === 0 ? (
                                <Text c="dimmed" ta="center">You haven't sold any items yet</Text>
                            ) : (
                                (userTransactions.sold || []).map((transaction: Transaction) =>
                                    transaction && transaction.id ? (
                                        <TransactionCard key={transaction.id} transaction={transaction} />
                                    ) : null
                                )
                            )}
                        </Stack>
                    </Tabs.Panel>

                    <Tabs.Panel value="borrowed" pt="md">
                        <Title order={3} mb="md">Items I Borrowed</Title>
                        <Text size="sm" c="dimmed" mb="lg">
                            Products you rented from others
                        </Text>
                        <Stack>
                            {(userTransactions.borrowed || []).length === 0 ? (
                                <Text c="dimmed" ta="center">You haven't borrowed any items yet</Text>
                            ) : (
                                (userTransactions.borrowed || []).map((transaction: Transaction) =>
                                    transaction && transaction.id ? (
                                        <TransactionCard key={transaction.id} transaction={transaction} />
                                    ) : null
                                )
                            )}
                        </Stack>
                    </Tabs.Panel>

                    <Tabs.Panel value="lent" pt="md">
                        <Title order={3} mb="md">Items I Lent</Title>
                        <Text size="sm" c="dimmed" mb="lg">
                            Products you lent to others
                        </Text>
                        <Stack>
                            {(userTransactions.lent || []).length === 0 ? (
                                <Text c="dimmed" ta="center">You haven't lent any items yet</Text>
                            ) : (
                                (userTransactions.lent || []).map((transaction: Transaction) =>
                                    transaction && transaction.id ? (
                                        <TransactionCard key={transaction.id} transaction={transaction} />
                                    ) : null
                                )
                            )}
                        </Stack>
                    </Tabs.Panel>
                </Tabs>
            )}
        </Container>
    );
};

export default MyTransactions;

import React, { useState, useEffect } from 'react';
import type { ReactNode } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { GET_CURRENT_USER, LOGIN_USER, LOGOUT_USER } from '../lib/graphql';
import type { User } from '../types';
import { isAuthenticated, logout } from '../lib/apollo-client';
import { AuthContext, type AuthContextType } from './AuthContextTypes';
import { AuthService, type AuthTokens } from '../services/auth';
import { useTokenRefresh } from '../hooks/useTokenRefresh';
import { useCacheManagement } from '../hooks/useCacheUpdates';

interface AuthProviderProps {
    children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [isAuth, setIsAuth] = useState(() => {
        // Check both new and old auth systems
        return AuthService.isAuthenticated() || isAuthenticated();
    });

    // Set up automatic token refresh for new auth system
    useTokenRefresh();

    // Cache management hooks
    const { clearUserSpecificData } = useCacheManagement();

    // GraphQL mutations
    const [loginUserMutation] = useMutation(LOGIN_USER);
    const [logoutUserMutation] = useMutation(LOGOUT_USER);

    const { data, loading, refetch } = useQuery(GET_CURRENT_USER, {
        skip: !isAuth,
        errorPolicy: 'all'
    });

    useEffect(() => {
        if (data?.getCurrentUser) {
            setUser(data.getCurrentUser);
        }
    }, [data]);

    const handleLogin = (token: string) => {
        // Support legacy auth system
        localStorage.setItem('token', token); // Legacy
        localStorage.setItem('accessToken', token); // New system

        // Clear any corrupted cache data to ensure fresh queries
        clearUserSpecificData();

        setIsAuth(true);
        refetch();
    };

    const handleLoginNew = async (email: string, password: string): Promise<AuthTokens> => {
        try {
            const result = await loginUserMutation({
                variables: { email, password }
            });

            if (result.data?.loginUser) {
                const { accessToken, refreshToken } = result.data.loginUser;

                // Store tokens
                localStorage.setItem('accessToken', accessToken);
                localStorage.setItem('refreshToken', refreshToken);

                // Clear any corrupted cache data to ensure fresh queries
                clearUserSpecificData();

                setIsAuth(true);
                await refetch();

                return { accessToken, refreshToken };
            }

            throw new Error('No login data received');
        } catch (error) {
            console.error('Login failed:', error);
            const message = error instanceof Error ? error.message : 'Login failed';
            throw new Error(message);
        }
    };

    const handleLogout = async () => {
        try {
            const refreshToken = localStorage.getItem('refreshToken');

            if (refreshToken && AuthService.isAuthenticated()) {
                // Use GraphQL mutation for logout
                await logoutUserMutation({
                    variables: { refreshToken }
                });
            } else if (localStorage.getItem('token')) {
                // Use legacy logout
                logout();
            }
        } catch (error) {
            console.error('Logout error:', error);
            // Continue with logout even if server request fails
        } finally {
            // Always clear local storage and state
            AuthService.clearTokens();

            // Clear user-specific data from Apollo cache
            clearUserSpecificData();

            setUser(null);
            setIsAuth(false);
        }
    };

    const contextValue: AuthContextType = {
        user,
        loading,
        login: handleLogin,
        loginNew: handleLoginNew,
        logout: handleLogout,
        isAuthenticated: isAuth,
        refetchUser: refetch
    };

    return <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>;
};

import { createContext } from 'react';
import type { User } from '../types';
import type { AuthTokens } from '../services/auth';

export interface AuthContextType {
    user: User | null;
    loading: boolean;
    login: (token: string) => void;
    loginNew: (email: string, password: string) => Promise<AuthTokens>;
    logout: () => Promise<void>;
    isAuthenticated: boolean;
    refetchUser: () => void;
}

export const AuthContext = createContext<AuthContextType | undefined>(undefined);

import { useContext } from 'react';
import { AuthContext } from '../contexts/AuthContextTypes';

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

export interface AuthTokens {
    accessToken: string;
    refreshToken: string;
}

export class AuthService {
    private static readonly ACCESS_TOKEN_KEY = 'accessToken';
    private static readonly REFRESH_TOKEN_KEY = 'refreshToken';

    // Login with GraphQL mutation
    static async login(email: string, password: string): Promise<AuthTokens> {
        const response = await fetch((import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') + '/graphql', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            credentials: 'include',
            body: JSON.stringify({
                query: `
                    mutation LoginUser($email: String!, $password: String!) {
                        loginUser(email: $email, password: $password) {
                            accessToken
                            refreshToken
                        }
                    }
                `,
                variables: { email, password }
            }),
        });

        const result = await response.json();

        if (result.errors) {
            throw new Error(result.errors[0].message);
        }

        const { accessToken, refreshToken } = result.data.loginUser;

        // Store both tokens in localStorage
        localStorage.setItem(this.ACCESS_TOKEN_KEY, accessToken);
        localStorage.setItem(this.REFRESH_TOKEN_KEY, refreshToken);

        return { accessToken, refreshToken };
    }

    // Refresh access token using GraphQL
    static async refreshToken(): Promise<string | null> {
        try {
            const refreshToken = localStorage.getItem(this.REFRESH_TOKEN_KEY);
            if (!refreshToken) {
                throw new Error('No refresh token available');
            }

            const response = await fetch((import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') + '/graphql', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                credentials: 'include',
                body: JSON.stringify({
                    query: `
                        mutation RefreshTokens($refreshToken: String!) {
                            refreshTokens(refreshToken: $refreshToken) {
                                accessToken
                                refreshToken
                            }
                        }
                    `,
                    variables: { refreshToken }
                }),
            });

            const result = await response.json();

            if (result.errors) {
                throw new Error(result.errors[0].message);
            }

            const { accessToken, refreshToken: newRefreshToken } = result.data.refreshTokens;
            localStorage.setItem(this.ACCESS_TOKEN_KEY, accessToken);
            localStorage.setItem(this.REFRESH_TOKEN_KEY, newRefreshToken);

            return accessToken;
        } catch (error) {
            console.error('Token refresh failed:', error);
            // Clear invalid tokens
            this.clearTokens();
            return null;
        }
    }

    // Logout using GraphQL
    static async logout(): Promise<void> {
        try {
            const refreshToken = localStorage.getItem(this.REFRESH_TOKEN_KEY);

            if (refreshToken) {
                await fetch((import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') + '/graphql', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    credentials: 'include',
                    body: JSON.stringify({
                        query: `
                            mutation LogoutUser($refreshToken: String!) {
                                logoutUser(refreshToken: $refreshToken)
                            }
                        `,
                        variables: { refreshToken }
                    }),
                });
            }
        } catch (error) {
            console.error('Logout request failed:', error);
        } finally {
            // Always clear local storage
            this.clearTokens();
        }
    }

    // Clear all tokens
    static clearTokens(): void {
        localStorage.removeItem(this.ACCESS_TOKEN_KEY);
        localStorage.removeItem(this.REFRESH_TOKEN_KEY);
        localStorage.removeItem('token'); // Legacy token cleanup
    }

    // Check if user is authenticated
    static isAuthenticated(): boolean {
        return !!localStorage.getItem(this.ACCESS_TOKEN_KEY) && !!localStorage.getItem(this.REFRESH_TOKEN_KEY);
    }

    // Get access token
    static getAccessToken(): string | null {
        return localStorage.getItem(this.ACCESS_TOKEN_KEY);
    }

    // Get refresh token
    static getRefreshToken(): string | null {
        return localStorage.getItem(this.REFRESH_TOKEN_KEY);
    }

    // Legacy login support (for backward compatibility)
    static async loginLegacy(email: string, password: string): Promise<string> {
        const response = await fetch(import.meta.env.VITE_BACKEND_URL + '/graphql', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                query: `
          query GetToken($email: String!, $password: String!) {
            getToken(email: $email, password: $password)
          }
        `,
                variables: { email, password },
            }),
        });

        const result = await response.json();

        if (result.errors) {
            throw new Error(result.errors[0].message);
        }

        const token = result.data.getToken;
        localStorage.setItem('token', token); // Legacy key
        localStorage.setItem(this.ACCESS_TOKEN_KEY, token); // Also store in new key

        return token;
    }

    // Check if we should use new auth system
    static shouldUseNewAuth(): boolean {
        return import.meta.env.VITE_USE_NEW_AUTH === 'true' || true; // Default to new auth
    }
}

import { Request, Response, NextFunction } from 'express';
import { verifyAccessToken, TokenPayload } from '../lib/jwt.js';
import DB from '../lib/db.js';

export interface AuthenticatedRequest extends Request {
    user?: {
        id: number;
        email: string;
        firstname: string;
        lastname?: string | null;
    };
}

/**
 * Middleware to verify access token and attach user to request
 */
export const authenticateToken = async (
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction
): Promise<void> => {
    try {
        const authHeader = req.headers['authorization'];
        const token = authHeader && authHeader.startsWith('Bearer ')
            ? authHeader.substring(7)
            : null;

        if (!token) {
            res.status(401).json({
                error: 'Access token required',
                code: 'TOKEN_MISSING'
            });
            return;
        }

        // Verify JWT signature and expiration
        const payload: TokenPayload = verifyAccessToken(token);

        // Get user from database to ensure they still exist
        const user = await DB.user.findUnique({
            where: {
                id: payload.userId,
                deleted: false
            },
            select: {
                id: true,
                email: true,
                firstname: true,
                lastname: true
            }
        });

        if (!user) {
            res.status(401).json({
                error: 'User not found or inactive',
                code: 'USER_NOT_FOUND'
            });
            return;
        }

        // Attach user to request
        req.user = user;
        next();

    } catch (error) {
        if (error instanceof Error) {
            if (error.message.includes('expired')) {
                res.status(401).json({
                    error: 'Access token expired',
                    code: 'TOKEN_EXPIRED'
                });
            } else if (error.message.includes('invalid')) {
                res.status(401).json({
                    error: 'Invalid access token',
                    code: 'TOKEN_INVALID'
                });
            } else {
                res.status(401).json({
                    error: 'Authentication failed',
                    code: 'AUTH_FAILED'
                });
            }
        } else {
            res.status(500).json({
                error: 'Internal server error',
                code: 'INTERNAL_ERROR'
            });
        }
    }
};

/**
 * Optional authentication middleware - doesn't fail if no token provided
 */
export const optionalAuthentication = async (
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction
): Promise<void> => {
    try {
        const authHeader = req.headers['authorization'];
        const token = authHeader && authHeader.startsWith('Bearer ')
            ? authHeader.substring(7)
            : null;

        if (token) {
            try {
                const payload: TokenPayload = verifyAccessToken(token);
                const user = await DB.user.findUnique({
                    where: {
                        id: payload.userId,
                        deleted: false
                    },
                    select: {
                        id: true,
                        email: true,
                        firstname: true,
                        lastname: true
                    }
                });

                if (user) {
                    req.user = user;
                }
            } catch (error) {
                // Ignore token errors in optional auth
            }
        }

        next();
    } catch (error) {
        // Don't fail the request for optional auth errors
        next();
    }
};

/**
 * Middleware to extract refresh token from HTTP-only cookie
 */
export const extractRefreshToken = (
    req: Request & { refreshToken?: string },
    res: Response,
    next: NextFunction
): void => {
    try {
        // Try to get refresh token from HTTP-only cookie
        const refreshTokenFromCookie = req.cookies?.refreshToken;

        // Fallback to Authorization header for mobile/API usage
        const authHeader = req.headers['authorization'];
        const refreshTokenFromHeader = authHeader && authHeader.startsWith('Bearer ')
            ? authHeader.substring(7)
            : null;

        // Also check request body for refresh token
        const refreshTokenFromBody = req.body?.refreshToken;

        const refreshToken = refreshTokenFromCookie || refreshTokenFromHeader || refreshTokenFromBody;

        if (!refreshToken) {
            res.status(401).json({
                error: 'Refresh token required',
                code: 'REFRESH_TOKEN_MISSING'
            });
            return;
        }

        req.refreshToken = refreshToken;
        next();

    } catch (error) {
        res.status(500).json({
            error: 'Failed to extract refresh token',
            code: 'EXTRACTION_ERROR'
        });
    }
};

import { NumberInput, Select, Stack, Text, Switch, Group } from '@mantine/core';
import { useState } from 'react';
import type { ProductFormData } from '../../types';
import { RentOption } from '../../types';

interface PricingFormProps {
    data: ProductFormData;
    onChange: (data: Partial<ProductFormData>) => void;
}

const PricingForm = ({ data, onChange }: PricingFormProps) => {
    const [canBuy, setCanBuy] = useState(!!data.priceBuy);
    const [canRent, setCanRent] = useState(!!data.priceRent);

    const handleBuyToggle = (checked: boolean) => {
        setCanBuy(checked);
        if (!checked) {
            onChange({ priceBuy: undefined });
        }
    };

    const handleRentToggle = (checked: boolean) => {
        setCanRent(checked);
        if (!checked) {
            onChange({ priceRent: undefined, rentOption: undefined });
        }
    };

    const rentOptions = [
        { value: RentOption.DAILY, label: 'Per Day' },
        { value: RentOption.WEEKLY, label: 'Per Week' },
        { value: RentOption.MONTHLY, label: 'Per Month' },
    ];

    return (
        <Stack>
            <Text size="sm" c="dimmed">
                Set at least one pricing option for your product
            </Text>

            <Group>
                <Switch
                    label="Available for Purchase"
                    checked={canBuy}
                    onChange={(event) => handleBuyToggle(event.currentTarget.checked)}
                />
            </Group>

            {canBuy && (
                <NumberInput
                    label="Buy Price"
                    placeholder="0.00"
                    value={data.priceBuy || ''}
                    onChange={(value) => onChange({ priceBuy: Number(value) || undefined })}
                    min={0}
                    prefix="$"
                    decimalScale={2}
                />
            )}

            <Group>
                <Switch
                    label="Available for Rent"
                    checked={canRent}
                    onChange={(event) => handleRentToggle(event.currentTarget.checked)}
                />
            </Group>

            {canRent && (
                <>
                    <NumberInput
                        label="Rent Price"
                        placeholder="0.00"
                        value={data.priceRent || ''}
                        onChange={(value) => onChange({ priceRent: Number(value) || undefined })}
                        min={0}
                        prefix="$"
                        decimalScale={2}
                    />

                    <Select
                        label="Rent Period"
                        placeholder="Select rent period"
                        value={data.rentOption || null}
                        onChange={(value) => onChange({ rentOption: value as RentOption || undefined })}
                        data={rentOptions}
                    />
                </>
            )}
        </Stack>
    );
};

export default PricingForm;

import { NumberInput, Select, Stack, Text, Group, Card } from '@mantine/core';
import { useState, useEffect } from 'react';
import type { ProductFormData } from '../../types';
import { RentOption } from '../../types';

interface ProductPricingStepProps {
    data: ProductFormData;
    onChange: (data: Partial<ProductFormData>) => void;
}

const ProductPricingStep = ({ data, onChange }: ProductPricingStepProps) => {
    const [pricingType, setPricingType] = useState<'buy' | 'rent' | 'both'>(() => {
        if (data.priceBuy && data.priceRent) return 'both';
        if (data.priceBuy) return 'buy';
        if (data.priceRent) return 'rent';
        return 'buy';
    });

    useEffect(() => {
        // Clear irrelevant fields when pricing type changes
        if (pricingType === 'buy') {
            onChange({ priceRent: undefined, rentOption: undefined });
        } else if (pricingType === 'rent') {
            onChange({ priceBuy: undefined });
        }
    }, [pricingType, onChange]);

    const rentOptions = [
        { value: RentOption.DAILY, label: 'Per Day' },
        { value: RentOption.WEEKLY, label: 'Per Week' },
        { value: RentOption.MONTHLY, label: 'Per Month' },
    ];

    return (
        <Stack align="center" mt="xl" px={{ base: "md", sm: 0 }}>
            <Text size="lg" fw={500} mb="md">Select Pricing Options</Text>

            <Group mb="xl" justify="center" wrap="wrap" gap="sm">
                <Card
                    shadow="sm"
                    padding="lg"
                    radius="md"
                    withBorder
                    style={{
                        cursor: 'pointer',
                        backgroundColor: pricingType === 'buy' ? 'var(--mantine-color-blue-0)' : undefined,
                        borderColor: pricingType === 'buy' ? 'var(--mantine-color-blue-5)' : undefined,
                    }}
                    onClick={() => setPricingType('buy')}
                >
                    <Text fw={500} ta="center">Sale Only</Text>
                </Card>

                <Card
                    shadow="sm"
                    padding="lg"
                    radius="md"
                    withBorder
                    style={{
                        cursor: 'pointer',
                        backgroundColor: pricingType === 'rent' ? 'var(--mantine-color-blue-0)' : undefined,
                        borderColor: pricingType === 'rent' ? 'var(--mantine-color-blue-5)' : undefined,
                    }}
                    onClick={() => setPricingType('rent')}
                >
                    <Text fw={500} ta="center">Rent Only</Text>
                </Card>

                <Card
                    shadow="sm"
                    padding="lg"
                    radius="md"
                    withBorder
                    style={{
                        cursor: 'pointer',
                        backgroundColor: pricingType === 'both' ? 'var(--mantine-color-blue-0)' : undefined,
                        borderColor: pricingType === 'both' ? 'var(--mantine-color-blue-5)' : undefined,
                    }}
                    onClick={() => setPricingType('both')}
                >
                    <Text fw={500} ta="center">Sale & Rent</Text>
                </Card>
            </Group>

            <Stack w={{ base: "100%", sm: 400 }} maw={400}>
                {(pricingType === 'buy' || pricingType === 'both') && (
                    <NumberInput
                        label="Sale Price"
                        placeholder="0.00"
                        value={data.priceBuy || ''}
                        onChange={(value) => onChange({ priceBuy: Number(value) || undefined })}
                        min={0}
                        prefix="$"
                        decimalScale={2}
                        size="lg"
                    />
                )}

                {(pricingType === 'rent' || pricingType === 'both') && (
                    <>
                        <NumberInput
                            label="Rent Price"
                            placeholder="0.00"
                            value={data.priceRent || ''}
                            onChange={(value) => onChange({ priceRent: Number(value) || undefined })}
                            min={0}
                            prefix="$"
                            decimalScale={2}
                            size="lg"
                        />

                        <Select
                            label="Rent Period"
                            placeholder="Select rent period"
                            value={data.rentOption || null}
                            onChange={(value) => onChange({ rentOption: value as RentOption || undefined })}
                            data={rentOptions}
                            size="lg"
                        />
                    </>
                )}
            </Stack>
        </Stack>
    );
};

